alter table public."OrderItem" add column if not exists "variantId" text;
alter table public."OrderItem" add column if not exists "variantSkuSnapshot" text not null default '';
alter table public."OrderItem" add column if not exists "variantAttributesSnapshot" text not null default '{}';
do $$ begin
 if not exists(select 1 from pg_constraint where conname='OrderItem_variantId_fkey') then
  alter table public."OrderItem" add constraint "OrderItem_variantId_fkey" foreign key ("variantId") references public."ProductVariant"(id) on delete set null;
 end if;
end $$;
create index if not exists "OrderItem_variantId_idx" on public."OrderItem"("variantId");

create or replace function public.admin_brands_search(p_token text,p_search text default '',p_status text default '') returns jsonb language plpgsql security definer set search_path=public as $$
declare v_admin public."AdminUser"%rowtype; v_q text:=lower(trim(coalesce(p_search,''))); begin
 v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if;
 return coalesce((select jsonb_agg(to_jsonb(x) order by x.name) from (select b.id,b.slug,b.name,b.description,b."logoUrl",b."websiteUrl",b."isPublished",b."createdAt",b."updatedAt",count(p.id)::int as "productCount" from public."Brand" b left join public."Product" p on p."brandId"=b.id where (v_q='' or lower(b.name) like '%'||v_q||'%' or lower(b.slug) like '%'||v_q||'%' or lower(coalesce(b.description,'')) like '%'||v_q||'%' or lower(coalesce(b."websiteUrl",'')) like '%'||v_q||'%') and (coalesce(p_status,'')='' or (p_status='PUBLISHED' and b."isPublished") or (p_status='DRAFT' and not b."isPublished")) group by b.id) x),'[]'::jsonb);
end $$;

create or replace function public.admin_upsert_brand(p_token text,p_data jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_admin public."AdminUser"%rowtype; v_id text:=nullif(trim(coalesce(p_data->>'id','')),''); v_name text:=trim(coalesce(p_data->>'name','')); v_slug text:=lower(trim(coalesce(p_data->>'slug',''))); begin
 v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; if char_length(v_name)<2 or char_length(v_name)>120 then raise exception 'invalid brand name'; end if; if v_slug='' then v_slug:=lower(regexp_replace(v_name,'[^a-zA-Z0-9]+','-','g')); end if; v_slug:=trim(both '-' from v_slug); if v_slug='' or v_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' or char_length(v_slug)>100 then raise exception 'invalid brand slug'; end if; if exists(select 1 from public."Brand" where lower(name)=lower(v_name) and (v_id is null or id<>v_id)) then raise exception 'brand name already exists'; end if; if exists(select 1 from public."Brand" where slug=v_slug and (v_id is null or id<>v_id)) then raise exception 'brand slug already exists'; end if;
 if v_id is null then v_id:=gen_random_uuid()::text; insert into public."Brand"(id,slug,name,description,"logoUrl","websiteUrl","isPublished","createdAt","updatedAt") values(v_id,v_slug,v_name,left(coalesce(p_data->>'description',''),2000),left(coalesce(p_data->>'logoUrl',''),2048),left(coalesce(p_data->>'websiteUrl',''),2048),coalesce((p_data->>'isPublished')::boolean,true),now(),now()); else update public."Brand" set slug=v_slug,name=v_name,description=left(coalesce(p_data->>'description',''),2000),"logoUrl"=left(coalesce(p_data->>'logoUrl',''),2048),"websiteUrl"=left(coalesce(p_data->>'websiteUrl',''),2048),"isPublished"=coalesce((p_data->>'isPublished')::boolean,true),"updatedAt"=now() where id=v_id; if not found then raise exception 'brand not found'; end if; end if; return jsonb_build_object('id',v_id,'slug',v_slug,'name',v_name);
end $$;
create or replace function public.admin_archive_brand(p_token text,p_id text) returns boolean language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; update public."Brand" set "isPublished"=false,"updatedAt"=now() where id=p_id; return found; end $$;

create or replace function public.admin_product_variants(p_token text,p_product_id text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; if not exists(select 1 from public."Product" where id=p_product_id) then raise exception 'product not found'; end if; return coalesce((select jsonb_agg(to_jsonb(v) order by v."createdAt") from public."ProductVariant" v where v."productId"=p_product_id),'[]'::jsonb); end $$;
create or replace function public.admin_upsert_product_variant(p_token text,p_data jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_admin public."AdminUser"%rowtype; v_id text:=nullif(trim(coalesce(p_data->>'id','')),''); v_product text:=trim(coalesce(p_data->>'productId','')); v_name text:=trim(coalesce(p_data->>'name','')); v_sku text:=trim(coalesce(p_data->>'sku','')); v_price int; v_compare int; v_stock int; v_attrs jsonb; begin
 v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; if not exists(select 1 from public."Product" where id=v_product) then raise exception 'product not found'; end if; if char_length(v_name)<1 or char_length(v_name)>160 or char_length(v_sku)<1 or char_length(v_sku)>120 then raise exception 'invalid variant fields'; end if; if exists(select 1 from public."ProductVariant" where lower(sku)=lower(v_sku) and (v_id is null or id<>v_id)) or exists(select 1 from public."Product" where lower(sku)=lower(v_sku)) then raise exception 'sku already exists'; end if; begin v_price:=nullif(p_data->>'price','')::int; v_compare:=nullif(p_data->>'compareAtPrice','')::int; v_stock:=coalesce(nullif(p_data->>'stock','')::int,0); exception when others then raise exception 'invalid numeric value'; end; if v_price is not null and v_price<0 or v_compare is not null and v_compare<0 or v_stock<0 then raise exception 'invalid numeric value'; end if; begin v_attrs:=coalesce(nullif(p_data->>'attributes','')::jsonb,'{}'::jsonb); exception when others then raise exception 'invalid attributes json'; end; if jsonb_typeof(v_attrs)<>'object' then raise exception 'attributes must be object'; end if;
 if v_id is null then v_id:=gen_random_uuid()::text; insert into public."ProductVariant"(id,"productId",name,sku,price,"compareAtPrice",stock,attributes,"isPublished","createdAt","updatedAt") values(v_id,v_product,v_name,v_sku,v_price,v_compare,v_stock,v_attrs::text,coalesce((p_data->>'isPublished')::boolean,true),now(),now()); else update public."ProductVariant" set name=v_name,sku=v_sku,price=v_price,"compareAtPrice"=v_compare,stock=v_stock,attributes=v_attrs::text,"isPublished"=coalesce((p_data->>'isPublished')::boolean,true),"updatedAt"=now() where id=v_id and "productId"=v_product; if not found then raise exception 'variant not found'; end if; end if; return jsonb_build_object('id',v_id,'sku',v_sku);
end $$;
create or replace function public.admin_delete_product_variant(p_token text,p_id text) returns boolean language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; if exists(select 1 from public."OrderItem" where "variantId"=p_id) then update public."ProductVariant" set "isPublished"=false,"updatedAt"=now() where id=p_id; return found; end if; delete from public."ProductVariant" where id=p_id; return found; end $$;

create or replace function public.admin_products_bundle(p_token text,p_search text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; v_q text; begin v_admin:=public._admin_session_user(p_token); v_q:=lower(trim(coalesce(p_search,''))); return jsonb_build_object('products',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select p.id,p.slug,p."nameFa",p."nameTr",p."nameEn",p."nameAr",p.sku,p."brandId",coalesce(b.name,p.brand) as brand,p.price,p.stock,p."lowStockThreshold",p."isPublished",p."isFeatured",p."isNewArrival",p."createdAt",p."updatedAt",c.id as "categoryId",c."nameFa" as "categoryNameFa",c."nameTr" as "categoryNameTr",c."nameEn" as "categoryNameEn",c."nameAr" as "categoryNameAr",(select m.url from public."Media" m where m."productId"=p.id order by m."sortOrder",m."createdAt" limit 1) as image,(select count(*)::int from public."ProductVariant" v where v."productId"=p.id) as "variantCount" from public."Product" p join public."Category" c on c.id=p."categoryId" left join public."Brand" b on b.id=p."brandId" where v_q='' or lower(coalesce(p."nameFa",'')) like '%'||v_q||'%' or lower(coalesce(p."nameTr",'')) like '%'||v_q||'%' or lower(coalesce(p."nameEn",'')) like '%'||v_q||'%' or lower(coalesce(p."nameAr",'')) like '%'||v_q||'%' or lower(coalesce(p.sku,'')) like '%'||v_q||'%' or lower(coalesce(b.name,p.brand,'')) like '%'||v_q||'%' or lower(coalesce(c."nameFa",'')) like '%'||v_q||'%' or lower(coalesce(c."nameTr",'')) like '%'||v_q||'%' or lower(coalesce(c."nameEn",'')) like '%'||v_q||'%' or lower(coalesce(c."nameAr",'')) like '%'||v_q||'%' order by p."createdAt" desc limit 500) x),'categories',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select id,slug,"nameFa","nameTr","nameEn","nameAr",vertical::text as vertical,"order","isPublished" from public."Category" order by "order","nameFa") x),'brands',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select id,slug,name,"logoUrl","websiteUrl","isPublished" from public."Brand" order by name) x)); end $$;
create or replace function public.admin_product_detail(p_token text,p_id text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; v_product jsonb; begin v_admin:=public._admin_session_user(p_token); select to_jsonb(p) into v_product from public."Product" p where p.id=p_id; if v_product is null then return null; end if; return v_product || jsonb_build_object('images',(select coalesce(jsonb_agg(to_jsonb(m) order by m."sortOrder",m."createdAt"),'[]'::jsonb) from public."Media" m where m."productId"=p_id),'categories',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select id,"nameFa","nameTr","nameEn","nameAr",vertical::text as vertical from public."Category" where "isPublished"=true order by "order","nameFa") x),'brands',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (select id,slug,name,"isPublished" from public."Brand" order by name) x),'variants',(select coalesce(jsonb_agg(to_jsonb(v) order by v."createdAt"),'[]'::jsonb) from public."ProductVariant" v where v."productId"=p_id)); end $$;
create or replace function public.admin_set_product_brand(p_token text,p_product_id text,p_brand_id text) returns boolean language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; v_name text; begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; if nullif(trim(coalesce(p_brand_id,'')),'') is null then update public."Product" set "brandId"=null,brand='',"updatedAt"=now() where id=p_product_id; return found; end if; select name into v_name from public."Brand" where id=p_brand_id; if not found then raise exception 'invalid brand'; end if; update public."Product" set "brandId"=p_brand_id,brand=v_name,"updatedAt"=now() where id=p_product_id; return found; end $$;

create or replace function public.create_guest_order(p_request_token uuid,p_customer_name text,p_phone text,p_email text,p_address text,p_province text,p_city text,p_country text,p_postal_code text,p_notes text,p_locale text,p_lines jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_existing public."Order"%rowtype; v_order_id text; v_order_number text; v_checkout_token uuid; v_result_token uuid; v_subtotal bigint:=0; v_total bigint:=0; v_line jsonb; v_type text; v_item_id text; v_variant_id text; v_qty int; v_name text; v_price int; v_product public."Product"%rowtype; v_variant public."ProductVariant"%rowtype; v_service public."Service"%rowtype; v_preferred timestamp; v_seen text[]:=array[]::text[]; v_reserved int; v_reservation_expires timestamp:=now()+interval '30 minutes'; begin
 if p_request_token is null then raise exception 'request token required'; end if; select * into v_existing from public."Order" where "requestToken"=p_request_token limit 1; if found then return jsonb_build_object('orderId',v_existing.id,'orderNumber',v_existing."orderNumber",'total',v_existing.total,'checkoutToken',v_existing."checkoutToken",'resultToken',v_existing."resultToken",'status',v_existing.status::text,'reservationExpiresAt',v_existing."reservationExpiresAt"); end if; if p_customer_name is null or char_length(trim(p_customer_name)) not between 2 and 120 or p_phone is null or char_length(trim(p_phone)) not between 8 and 24 or p_address is null or char_length(trim(p_address)) not between 5 and 500 or p_city is null or char_length(trim(p_city)) not between 2 and 120 then raise exception 'invalid order metadata'; end if; if p_email is not null and char_length(trim(p_email))>254 then raise exception 'invalid email'; end if; if char_length(coalesce(trim(p_province),''))>120 or char_length(coalesce(trim(p_country),''))>120 or char_length(coalesce(trim(p_postal_code),''))>20 or char_length(coalesce(trim(p_notes),''))>1000 then raise exception 'invalid order metadata'; end if; if coalesce(p_locale,'') not in ('fa','tr','en','ar') then raise exception 'invalid locale'; end if; if p_lines is null or jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)<1 or jsonb_array_length(p_lines)>100 then raise exception 'invalid lines'; end if;
 v_order_id:=gen_random_uuid()::text; v_checkout_token:=gen_random_uuid(); v_result_token:=gen_random_uuid(); v_order_number:='HD-'||to_char(clock_timestamp(),'YYYYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)); insert into public."Order"(id,"orderNumber","requestToken","checkoutToken","resultToken","customerName",phone,email,address,province,city,country,"postalCode",notes,locale,currency,subtotal,"discountAmount","shippingFee",total,status,gateway,"shippingMethod","trackingCode","reservationExpiresAt","createdAt","updatedAt") values(v_order_id,v_order_number,p_request_token,v_checkout_token,v_result_token,trim(p_customer_name),trim(p_phone),nullif(trim(p_email),''),trim(p_address),coalesce(trim(p_province),''),trim(p_city),coalesce(trim(p_country),''),nullif(trim(p_postal_code),''),coalesce(trim(p_notes),''),p_locale,'IRT',0,0,0,0,'PENDING_PAYMENT'::"OrderStatus",'ZARINPAL'::"PaymentGateway",'','',v_reservation_expires,now(),now());
 for v_line in select value from jsonb_array_elements(p_lines) loop if jsonb_typeof(v_line)<>'object' then raise exception 'invalid order line'; end if; v_type:=v_line->>'type'; v_item_id:=nullif(btrim(v_line->>'id'),''); v_variant_id:=nullif(btrim(v_line->>'variantId'),''); begin v_qty:=(v_line->>'quantity')::int; exception when others then raise exception 'invalid quantity'; end; if v_item_id is null or char_length(v_item_id)>160 or v_qty<1 or v_qty>50 then raise exception 'invalid order line'; end if; if (v_type||':'||v_item_id||':'||coalesce(v_variant_id,''))=any(v_seen) then raise exception 'duplicate order line'; end if; v_seen:=array_append(v_seen,v_type||':'||v_item_id||':'||coalesce(v_variant_id,'')); v_preferred:=null; if nullif(v_line->>'preferredDate','') is not null then begin v_preferred:=(v_line->>'preferredDate')::timestamp; exception when others then raise exception 'invalid preferred date'; end; end if;
 if v_type='product' then if v_preferred is not null then raise exception 'preferred date is not valid for products'; end if; select * into v_product from public."Product" where id=v_item_id and "isPublished"=true for update; if not found then raise exception 'product unavailable'; end if; if exists(select 1 from public."ProductVariant" where "productId"=v_product.id and "isPublished"=true) then if v_variant_id is null then raise exception 'variant required'; end if; select * into v_variant from public."ProductVariant" where id=v_variant_id and "productId"=v_product.id and "isPublished"=true for update; if not found then raise exception 'variant unavailable'; end if; v_price:=coalesce(v_variant.price,v_product.price); if v_price<=0 then raise exception 'invalid product price'; end if; select coalesce(sum(oi.quantity),0)::int into v_reserved from public."OrderItem" oi join public."Order" o on o.id=oi."orderId" where oi."variantId"=v_variant.id and o.status='PENDING_PAYMENT'::"OrderStatus" and o."reservationExpiresAt">now(); if v_variant.stock-v_reserved<v_qty then raise exception 'insufficient variant stock'; end if; else if v_variant_id is not null then raise exception 'variant unavailable'; end if; v_price:=v_product.price; if v_price<=0 then raise exception 'invalid product price'; end if; select coalesce(sum(oi.quantity),0)::int into v_reserved from public."OrderItem" oi join public."Order" o on o.id=oi."orderId" where oi."productId"=v_product.id and oi."variantId" is null and o.status='PENDING_PAYMENT'::"OrderStatus" and o."reservationExpiresAt">now(); if v_product.stock-v_reserved<v_qty then raise exception 'insufficient stock'; end if; end if; if v_qty<greatest(coalesce(v_product."minOrderQty",1),1) then raise exception 'minimum order quantity is %',greatest(coalesce(v_product."minOrderQty",1),1); end if; if v_product."maxOrderQty" is not null and v_qty>v_product."maxOrderQty" then raise exception 'maximum order quantity is %',v_product."maxOrderQty"; end if; v_name:=case p_locale when 'fa' then v_product."nameFa" when 'tr' then coalesce(nullif(v_product."nameTr",''),v_product."nameEn") when 'ar' then coalesce(nullif(v_product."nameAr",''),v_product."nameEn") else v_product."nameEn" end; if v_variant_id is not null then v_name:=v_name||' — '||v_variant.name; end if; insert into public."OrderItem"(id,"orderId","productId","serviceId","variantId","variantSkuSnapshot","variantAttributesSnapshot","nameSnapshot","priceSnapshot",quantity,"preferredDate") values(gen_random_uuid()::text,v_order_id,v_product.id,null,v_variant_id,coalesce(v_variant.sku,''),coalesce(v_variant.attributes,'{}'),v_name,v_price,v_qty,null);
 elsif v_type='service' then if v_qty<>1 then raise exception 'service quantity must be one'; end if; select * into v_service from public."Service" where id=v_item_id and "isPublished"=true; if not found then raise exception 'service unavailable'; end if; if v_service.price is null or v_service.price<=0 then raise exception 'service requires booking instead of checkout'; end if; v_price:=v_service.price; v_name:=case p_locale when 'fa' then v_service."nameFa" when 'tr' then coalesce(nullif(v_service."nameTr",''),v_service."nameEn") when 'ar' then coalesce(nullif(v_service."nameAr",''),v_service."nameEn") else v_service."nameEn" end; insert into public."OrderItem"(id,"orderId","productId","serviceId","variantId","nameSnapshot","priceSnapshot",quantity,"preferredDate") values(gen_random_uuid()::text,v_order_id,null,v_service.id,null,v_name,v_price,1,v_preferred); else raise exception 'invalid line type'; end if; if v_price::bigint*v_qty::bigint>2147483647 then raise exception 'order line total too large'; end if; v_subtotal:=v_subtotal+v_price::bigint*v_qty::bigint; if v_subtotal>2147483647 then raise exception 'order total too large'; end if; end loop; if v_subtotal<=0 then raise exception 'order total must be greater than zero'; end if; v_total:=v_subtotal; update public."Order" set subtotal=v_subtotal::int,total=v_total::int,"updatedAt"=now() where id=v_order_id; return jsonb_build_object('orderId',v_order_id,'orderNumber',v_order_number,'total',v_total,'checkoutToken',v_checkout_token,'resultToken',v_result_token,'status','PENDING_PAYMENT','reservationExpiresAt',v_reservation_expires);
exception when unique_violation then select * into v_existing from public."Order" where "requestToken"=p_request_token limit 1; if found then return jsonb_build_object('orderId',v_existing.id,'orderNumber',v_existing."orderNumber",'total',v_existing.total,'checkoutToken',v_existing."checkoutToken",'resultToken',v_existing."resultToken",'status',v_existing.status::text,'reservationExpiresAt',v_existing."reservationExpiresAt"); end if; raise; end $$;

create or replace function public.finalize_order_payment(p_order_number text,p_checkout_token uuid,p_authority text,p_success boolean,p_ref_id text) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_order public."Order"%rowtype; v_item public."OrderItem"%rowtype; v_product public."Product"%rowtype; v_variant public."ProductVariant"%rowtype; v_conflict boolean:=false; begin select * into v_order from public."Order" where "orderNumber"=p_order_number and "checkoutToken"=p_checkout_token and "paymentAuthority"=p_authority for update; if not found then return null; end if; if v_order.status in ('PAID'::"OrderStatus",'PROCESSING'::"OrderStatus",'SHIPPED'::"OrderStatus",'COMPLETED'::"OrderStatus") then return jsonb_build_object('orderNumber',v_order."orderNumber",'status',v_order.status::text,'locale',v_order.locale,'resultToken',v_order."resultToken"); end if; if v_order.status='PAYMENT_REVIEW'::"OrderStatus" then return jsonb_build_object('orderNumber',v_order."orderNumber",'status','PAYMENT_REVIEW','locale',v_order.locale,'resultToken',v_order."resultToken"); end if; if v_order.status in ('FAILED'::"OrderStatus",'CANCELLED'::"OrderStatus",'REFUNDED'::"OrderStatus") then return jsonb_build_object('orderNumber',v_order."orderNumber",'status',v_order.status::text,'locale',v_order.locale,'resultToken',v_order."resultToken"); end if; if v_order.status<>'PENDING_PAYMENT'::"OrderStatus" then return jsonb_build_object('orderNumber',v_order."orderNumber",'status',v_order.status::text,'locale',v_order.locale,'resultToken',v_order."resultToken"); end if; if not p_success then update public."Order" set status='FAILED'::"OrderStatus","reservationExpiresAt"=null,"updatedAt"=now() where id=v_order.id; return jsonb_build_object('orderNumber',v_order."orderNumber",'status','FAILED','locale',v_order.locale,'resultToken',v_order."resultToken"); end if; if p_ref_id is null or char_length(btrim(p_ref_id))<1 or char_length(btrim(p_ref_id))>128 then raise exception 'valid payment reference required'; end if;
 for v_item in select * from public."OrderItem" where "orderId"=v_order.id and "productId" is not null order by "productId","variantId" nulls first loop if v_item."variantId" is not null then select * into v_variant from public."ProductVariant" where id=v_item."variantId" for update; if not found or v_item.quantity<1 or v_variant.stock<v_item.quantity then v_conflict:=true; exit; end if; else select * into v_product from public."Product" where id=v_item."productId" for update; if not found or v_item.quantity<1 or v_product.stock<v_item.quantity then v_conflict:=true; exit; end if; end if; end loop; if v_conflict then update public."Order" set status='PAYMENT_REVIEW'::"OrderStatus","paymentRefId"=btrim(p_ref_id),"reservationExpiresAt"=null,"updatedAt"=now() where id=v_order.id; return jsonb_build_object('orderNumber',v_order."orderNumber",'status','PAYMENT_REVIEW','locale',v_order.locale,'resultToken',v_order."resultToken"); end if;
 for v_item in select * from public."OrderItem" where "orderId"=v_order.id and "productId" is not null order by "productId","variantId" nulls first loop if v_item."variantId" is not null then update public."ProductVariant" set stock=stock-v_item.quantity,"updatedAt"=now() where id=v_item."variantId"; else update public."Product" set stock=stock-v_item.quantity,"updatedAt"=now() where id=v_item."productId"; end if; end loop; update public."Order" set status='PAID'::"OrderStatus","paymentRefId"=btrim(p_ref_id),"reservationExpiresAt"=null,"updatedAt"=now() where id=v_order.id; return jsonb_build_object('orderNumber',v_order."orderNumber",'status','PAID','locale',v_order.locale,'resultToken',v_order."resultToken"); end $$;
